-- Banco de conteúdo curado: questões de quiz e flashcards REAIS, revisados
-- pela equipe, por matéria do ENEM. Hoje o Quiz IA e os Flashcards dependem
-- 100% de uma chamada à IA a cada "Gerar" (ver revisao.service.ts) — se a
-- IA estiver fora do ar, sem cota, ou sem chave configurada (como é o caso
-- agora), essas duas seções inteiras ficam inutilizáveis, e nenhuma outra
-- parte do produto oferece conteúdo de estudo que não passe pela IA.
--
-- Estas duas tabelas resolvem isso: dão ao aluno um banco de prática
-- pronto, sem custo de API e sem depender de uma IA no ar, como
-- complemento (não substituto) à geração por IA. O aluno escolhe: praticar
-- agora com o banco, ou gerar um lote novo com a IA quando ela estiver
-- disponível.
--
-- `materia` guarda o nome exatamente como o frontend reconhece em
-- core/areas.ts (AREA_POR_MATERIA), para o aluno achar conteúdo pronto ao
-- cadastrar uma matéria com esse nome. `area` é a área do ENEM (linguagens,
-- humanas, natureza, matematica), guardada apenas como metadado de
-- filtragem futura — a consulta de hoje filtra só por `materia`.

CREATE TABLE tb_banco_questoes (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    area          VARCHAR(20)  NOT NULL,
    materia       VARCHAR(100) NOT NULL,
    topico        VARCHAR(150),
    enunciado     TEXT         NOT NULL,
    alternativa_a TEXT         NOT NULL,
    alternativa_b TEXT         NOT NULL,
    alternativa_c TEXT         NOT NULL,
    alternativa_d TEXT         NOT NULL,
    correta       VARCHAR(1)   NOT NULL CHECK (correta IN ('A', 'B', 'C', 'D')),
    explicacao    TEXT
);

CREATE INDEX idx_banco_questoes_materia_lower ON tb_banco_questoes (lower(materia));

CREATE TABLE tb_banco_flashcards (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    area    VARCHAR(20)  NOT NULL,
    materia VARCHAR(100) NOT NULL,
    topico  VARCHAR(150),
    frente  TEXT         NOT NULL,
    verso   TEXT         NOT NULL
);

CREATE INDEX idx_banco_flashcards_materia_lower ON tb_banco_flashcards (lower(materia));

