INSERT INTO tb_banco_questoes (area, materia, topico, enunciado, alternativa_a, alternativa_b, alternativa_c, alternativa_d, correta, explicacao) VALUES
('matematica', 'Matemática', 'Porcentagem', 'Um produto custava R$ 80,00 e teve um desconto de 15%. Qual o novo preço?', 'R$ 68,00', 'R$ 65,00', 'R$ 12,00', 'R$ 92,00', 'A', '15% de 80 é 12; 80 − 12 = 68.'),
('matematica', 'Matemática', 'Função afim', 'Na função f(x) = 2x + 3, qual é o valor de f(5)?', '10', '13', '8', '7', 'B', '2 × 5 + 3 = 13.'),
('matematica', 'Matemática', 'Regra de três', 'Se 4 operários constroem um muro em 12 dias, quantos dias 6 operários levam para construir o mesmo muro, no mesmo ritmo?', '6', '8', '18', '10', 'B', 'É uma grandeza inversamente proporcional: 4 × 12 = 48; 48 ÷ 6 = 8 dias.'),
('linguagens', 'Português', 'Figuras de linguagem', 'Qual figura de linguagem está presente em "Seus olhos são dois sóis"?', 'Metáfora', 'Metonímia', 'Hipérbole', 'Antítese', 'A', 'A metáfora faz uma comparação implícita, sem conectivo, entre os olhos e o sol.'),
('linguagens', 'Português', 'Concordância verbal', 'Qual frase está de acordo com a norma-padrão?', '"Fazem dois anos que ele se mudou."', '"Faz dois anos que ele se mudou."', '"Fazeram dois anos que ele se mudou."', '"Fazem-se dois anos que ele se mudou."', 'B', 'O verbo "fazer" indicando tempo decorrido é impessoal e fica sempre na 3ª pessoa do singular.'),
('linguagens', 'Português', 'Redação ENEM', 'No texto dissertativo-argumentativo do ENEM, qual elemento é obrigatório na conclusão?', 'Proposta de intervenção', 'Uma nova tese', 'Uma citação direta', 'Uma pergunta retórica', 'A', 'A competência 5 da matriz do ENEM exige uma proposta de intervenção para o problema discutido, respeitando os direitos humanos.'),
('humanas', 'História', 'Revolução Industrial', 'A Revolução Industrial teve início, no século XVIII, em qual país?', 'França', 'Inglaterra', 'Alemanha', 'Estados Unidos', 'B', 'A Inglaterra reunia as condições (capital, mão de obra, matéria-prima e mercado) que deram início ao processo.'),
('humanas', 'História', 'Independência do Brasil', 'A independência do Brasil, em 1822, foi proclamada por quem?', 'Dom Pedro I', 'Dom João VI', 'Tiradentes', 'Getúlio Vargas', 'A', 'Dom Pedro I proclamou a independência às margens do rio Ipiranga, em 7 de setembro de 1822.'),
('humanas', 'História', 'Era Vargas', 'O primeiro governo de Getúlio Vargas no Brasil ocorreu em qual período?', '1822–1889', '1930–1945', '1964–1985', '1889–1930', 'B', 'Vargas chegou ao poder pela Revolução de 1930 e governou, com a ditadura do Estado Novo, até 1945.'),
('humanas', 'Geografia', 'Biomas brasileiros', 'Qual é o maior bioma brasileiro em extensão territorial?', 'Mata Atlântica', 'Cerrado', 'Amazônia', 'Caatinga', 'C', 'A Amazônia ocupa cerca de 49% do território nacional, sendo o maior bioma do país.'),
('humanas', 'Geografia', 'Climatologia', 'O fenômeno El Niño está relacionado a quê?', 'Aquecimento das águas do oceano Pacífico', 'Degelo dos polos', 'Erupções vulcânicas', 'Desmatamento da Amazônia', 'A', 'El Niño é o aquecimento anormal das águas superficiais do Pacífico equatorial, que altera padrões climáticos globais.'),
('humanas', 'Geografia', 'Migrações', 'Qual conceito define o deslocamento de pessoas de um país para outro em busca de melhores condições de vida?', 'Êxodo rural', 'Migração', 'Urbanização', 'Segregação espacial', 'B', 'Migração é o termo geral para o deslocamento populacional; quando é entre países, também é chamada de migração internacional.'),
('natureza', 'Física', 'Unidades de medida', 'Qual é a unidade de medida de força no Sistema Internacional?', 'Joule', 'Newton', 'Watt', 'Pascal', 'B', 'O newton (N) é a unidade de força; joule mede energia, watt mede potência e pascal mede pressão.'),
('natureza', 'Física', 'Queda livre', 'Um corpo em queda livre, desprezando a resistência do ar, tem aceleração aproximada de:', '5,8 m/s²', '8,9 m/s²', '9,8 m/s²', '11,2 m/s²', 'C', 'A aceleração da gravidade ao nível do mar é aproximadamente 9,8 m/s².'),
('natureza', 'Física', 'Leis de Newton', 'A 1ª Lei de Newton (Lei da Inércia) afirma que:', 'Todo corpo tende a permanecer em repouso ou em movimento retilíneo uniforme, salvo força resultante não nula', 'Força é igual a massa vezes aceleração', 'Toda ação gera uma reação de mesma intensidade', 'A energia não pode ser criada nem destruída', 'A', 'É a definição da Lei da Inércia; as demais alternativas descrevem a 2ª Lei de Newton, a 3ª Lei de Newton e a conservação de energia, respectivamente.'),
('natureza', 'Química', 'Tabela periódica', 'Qual é o símbolo químico do sódio?', 'S', 'So', 'Na', 'Nd', 'C', 'O símbolo vem do latim "natrium". "S" é enxofre e "Nd" é neodímio.'),
('natureza', 'Química', 'pH', 'O pH de uma solução neutra, a 25 °C, é igual a:', '0', '7', '14', '10', 'B', 'pH 7 é neutro; abaixo de 7 a solução é ácida e acima de 7 é básica.'),
('natureza', 'Química', 'Termoquímica', 'Reações exotérmicas são aquelas que:', 'Absorvem calor do ambiente', 'Liberam calor para o ambiente', 'Não trocam calor com o ambiente', 'Ocorrem apenas em meio aquoso', 'B', 'Exo = "para fora": a reação libera energia térmica para o ambiente, geralmente aquecendo-o.'),
('natureza', 'Biologia', 'Citologia', 'A mitocôndria é chamada de "usina de energia" da célula por ser responsável por qual processo?', 'Fotossíntese', 'Respiração celular', 'Síntese de proteínas', 'Divisão celular', 'B', 'É na mitocôndria que ocorre a respiração celular, produzindo ATP a partir da quebra de glicose.'),
('natureza', 'Biologia', 'Genética', 'O DNA é composto por quatro bases nitrogenadas. Quais são elas?', 'Adenina, Guanina, Citosina, Timina', 'Adenina, Glicose, Citosina, Uracila', 'Guanina, Fosfato, Ribose, Timina', 'Adenina, Guanina, Uracila, Timina', 'A', 'No DNA, as bases são adenina (A), guanina (G), citosina (C) e timina (T); o RNA troca a timina pela uracila.'),
('natureza', 'Biologia', 'Fisiologia vegetal', 'O processo de fotossíntese ocorre principalmente em qual organela da célula vegetal?', 'Mitocôndria', 'Ribossomo', 'Cloroplasto', 'Núcleo', 'C', 'O cloroplasto contém a clorofila, pigmento responsável por captar a luz usada na fotossíntese.');
INSERT INTO tb_banco_flashcards (area, materia, topico, frente, verso) VALUES
('matematica', 'Matemática', 'Equação do 2º grau', 'Fórmula de Bhaskara', 'x = (−b ± √(b² − 4ac)) / 2a — resolve equações do 2º grau no formato ax² + bx + c = 0.'),
('matematica', 'Matemática', 'Geometria', 'Teorema de Pitágoras', 'Em um triângulo retângulo: a² = b² + c², onde a é a hipotenusa e b, c são os catetos.'),
('matematica', 'Matemática', 'Geometria', 'Área do círculo', 'A = π · r², onde r é o raio da circunferência.'),
('matematica', 'Matemática', 'Sequências', 'Progressão Aritmética (PA)', 'Sequência em que cada termo é obtido somando uma razão constante r ao termo anterior: aₙ = a₁ + (n − 1)·r.'),
('linguagens', 'Português', 'Sintaxe', 'Sujeito oculto', 'Sujeito que não aparece de forma explícita na oração, mas é identificável pela desinência verbal (ex.: "Estudamos muito" = nós).'),
('linguagens', 'Português', 'Sintaxe', 'Oração subordinada adverbial', 'Oração que exerce função de advérbio em relação à oração principal, expressando causa, condição, tempo, finalidade etc.'),
('linguagens', 'Português', 'Concordância', 'Concordância com "a maioria de"', 'O verbo pode concordar com "maioria" (singular) ou com o substantivo que a segue, no plural: "A maioria dos alunos estudou/estudaram".'),
('linguagens', 'Português', 'Redação ENEM', '5 competências da redação do ENEM', '1) Domínio da norma culta; 2) Compreensão do tema; 3) Organização de argumentos; 4) Mecanismos linguísticos (coesão); 5) Proposta de intervenção.'),
('humanas', 'História', 'Brasil República', 'Golpe de 1964', 'Movimento civil-militar que depôs o presidente João Goulart e deu início à ditadura militar no Brasil (1964–1985).'),
('humanas', 'História', 'História geral', 'Revolução Francesa', 'Iniciada em 1789, pôs fim ao Antigo Regime na França, difundindo os ideais de liberdade, igualdade e fraternidade.'),
('humanas', 'História', 'História geral', 'Guerra Fria', 'Disputa ideológica, política e militar entre EUA (capitalismo) e URSS (socialismo), de 1947 a 1991, sem confronto militar direto entre as potências.'),
('humanas', 'História', 'Brasil Império', 'Abolição da escravatura no Brasil', 'Lei Áurea, assinada pela Princesa Isabel em 13 de maio de 1888, aboliu a escravidão no país.'),
('humanas', 'Geografia', 'Meio ambiente', 'Efeito estufa', 'Fenômeno natural em que gases da atmosfera retêm calor; intensificado pela ação humana, causa o aquecimento global.'),
('humanas', 'Geografia', 'Geologia', 'Placas tectônicas', 'Grandes blocos da litosfera terrestre que se movem lentamente, causando terremotos, vulcões e cadeias montanhosas nas bordas.'),
('humanas', 'Geografia', 'Geografia econômica', 'Globalização', 'Processo de integração econômica, cultural e política entre países, intensificado pelas tecnologias de comunicação e transporte.'),
('humanas', 'Geografia', 'Cartografia', 'Fusos horários', 'Divisão da Terra em 24 faixas (uma por hora), baseada na longitude, a partir do Meridiano de Greenwich.'),
('natureza', 'Física', 'Mecânica', '2ª Lei de Newton', 'F = m · a — a força resultante sobre um corpo é igual ao produto de sua massa pela aceleração.'),
('natureza', 'Física', 'Mecânica', 'Energia cinética', 'Ec = (m · v²) / 2 — energia associada ao movimento de um corpo de massa m e velocidade v.'),
('natureza', 'Física', 'Cinemática', 'Velocidade média', 'Vm = ΔS / Δt — razão entre a variação do espaço percorrido e o tempo gasto para percorrê-lo.'),
('natureza', 'Física', 'Eletricidade', 'Lei de Ohm', 'U = R · i — a tensão elétrica é igual ao produto da resistência pela corrente elétrica.'),
('natureza', 'Química', 'Tabela periódica', 'Grupo (ou família) da tabela periódica', 'Colunas verticais da tabela periódica; elementos de um mesmo grupo têm propriedades químicas semelhantes.'),
('natureza', 'Química', 'Ligações químicas', 'Ligação iônica', 'Formada pela transferência de elétrons entre um metal (cátion) e um ametal (ânion), como em NaCl.'),
('natureza', 'Química', 'Estequiometria', 'Mol', 'Unidade de quantidade de matéria; 1 mol contém aproximadamente 6,02 × 10²³ partículas (número de Avogadro).'),
('natureza', 'Química', 'Ácidos e bases', 'Ácidos e bases (conceito de Arrhenius)', 'Ácidos liberam H⁺ em solução aquosa; bases liberam OH⁻ em solução aquosa.'),
('natureza', 'Biologia', 'Citologia', 'Fotossíntese', 'Processo pelo qual plantas e algas convertem luz solar, água e CO₂ em glicose e oxigênio, usando a clorofila nos cloroplastos.'),
('natureza', 'Biologia', 'Citologia', 'Mitose', 'Divisão celular que origina duas células-filhas geneticamente idênticas à célula-mãe, responsável pelo crescimento e reparo de tecidos.'),
('natureza', 'Biologia', 'Genética', 'Lei de Mendel (1ª Lei)', 'Lei da segregação dos fatores: cada característica é determinada por um par de genes (alelos) que se separam na formação dos gametas.'),
('natureza', 'Biologia', 'Ecologia', 'Cadeia alimentar', 'Sequência de seres vivos em que um serve de alimento para o seguinte, transferindo energia (produtores → consumidores → decompositores).');
